// src/store/cart.ts
import { create } from "zustand"
import { persist } from "zustand/middleware"

type Product = { id: number; name: string; price: number }
type CartItem = Product & { qty: number }

type CartState = {
  items: CartItem[]
  add: (product: Product) => void
  remove: (id: number) => void
  setQty: (id: number, qty: number) => void
  clear: () => void
  total: () => number
}

export const useCart = create<CartState>()(
  persist(
    (set, get) => ({
      items: [],
      add: (product) => set(state => {
        const existing = state.items.find(i => i.id === product.id)
        if (existing) {
          return {
            items: state.items.map(i =>
              i.id === product.id ? { ...i, qty: i.qty + 1 } : i
            ),
          }
        }
        return { items: [...state.items, { ...product, qty: 1 }] }
      }),
      remove: (id) => set(state => ({
        items: state.items.filter(i => i.id !== id),
      })),
      setQty: (id, qty) => set(state => ({
        items: state.items.map(i => i.id === id ? { ...i, qty } : i),
      })),
      clear: () => set({ items: [] }),
      total: () => get().items.reduce((sum, i) => sum + i.price * i.qty, 0),
    }),
    { name: "cart-storage" }  // disimpan di localStorage
  )
)

import { create, StateCreator } from "zustand"

type AuthSlice = { user: User | null; login: (...) => void }
type CartSlice = { items: CartItem[]; add: (...) => void }

const createAuthSlice: StateCreator<AuthSlice & CartSlice, [], [], AuthSlice> = (set) => ({
  user: null,
  login: (...) => set({ user: ... }),
})

const createCartSlice: StateCreator<AuthSlice & CartSlice, [], [], CartSlice> = (set) => ({
  items: [],
  add: (...) => set(state => ({ items: [...state.items, ...] })),
})

export const useStore = create<AuthSlice & CartSlice>()((...a) => ({
  ...createAuthSlice(...a),
  ...createCartSlice(...a),
}))

