// src/store/todoStore.ts
import { create } from "zustand"
import { persist } from "zustand/middleware"

export type Todo = {
  id: string
  text: string
  completed: boolean
  createdAt: number
}

type Filter = "all" | "active" | "completed"

type TodoState = {
  todos: Todo[]
  filter: Filter
  search: string
  add: (text: string) => void
  toggle: (id: string) => void
  remove: (id: string) => void
  edit: (id: string, text: string) => void
  setFilter: (f: Filter) => void
  setSearch: (q: string) => void
  toggleAll: () => void
  clearCompleted: () => void
}

export const useTodoStore = create<TodoState>()(
  persist(
    (set, get) => ({
      todos: [],
      filter: "all",
      search: "",
      add: (text) => {
        const trimmed = text.trim()
        if (!trimmed) return
        set(state => ({
          todos: [
            ...state.todos,
            { id: crypto.randomUUID(), text: trimmed, completed: false, createdAt: Date.now() },
          ],
        }))
      },
      toggle: (id) => set(state => ({
        todos: state.todos.map(t => t.id === id ? { ...t, completed: !t.completed } : t),
      })),
      remove: (id) => set(state => ({ todos: state.todos.filter(t => t.id !== id) })),
      edit: (id, text) => {
        const trimmed = text.trim()
        if (!trimmed) return get().remove(id)
        set(state => ({
          todos: state.todos.map(t => t.id === id ? { ...t, text: trimmed } : t),
        }))
      },
      setFilter: (filter) => set({ filter }),
      setSearch: (search) => set({ search }),
      toggleAll: () => set(state => {
        const allDone = state.todos.every(t => t.completed)
        return { todos: state.todos.map(t => ({ ...t, completed: !allDone })) }
      }),
      clearCompleted: () => set(state => ({ todos: state.todos.filter(t => !t.completed) })),
    }),
    { name: "todo-storage" }
  )
)

// src/api/meals.ts
import { useQuery } from "@tanstack/react-query"

const BASE = "https://www.themealdb.com/api/json/v1/1"

async function api<T>(url: string): Promise<T> {
  const res = await fetch(url)
  if (!res.ok) throw new Error(`HTTP ${res.status}`)
  return res.json()
}

export function useSearchMeals(q: string) {
  return useQuery({
    queryKey: ["meals", "search", q],
    queryFn: () => api<{ meals: Meal[] | null }>(`${BASE}/search.php?s=${q}`),
    enabled: q.length > 0,
    staleTime: 5 * 60_000,
  })
}

export function useMealDetail(id: string) {
  return useQuery({
    queryKey: ["meals", id],
    queryFn: () => api<{ meals: MealDetail[] }>(`${BASE}/lookup.php?i=${id}`),
    enabled: !!id,
  })
}

