  return (
    <form className="form" onSubmit={handleSubmit}>
      <input
        placeholder="Deskripsi"
        value={deskripsi}
        onChange={(e) => setDeskripsi(e.target.value)}
      />
      <input
        type="number"
        placeholder="Jumlah"
        value={jumlah}
        onChange={(e) => setJumlah(e.target.value)}
      />
      <select value={jenis} onChange={(e) => setJenis(e.target.value)}>
