function Ringkasan({ transaksi }) {
  const pemasukan = transaksi
    .filter((t) => t.jenis === 'pemasukan')
    .reduce((total, t) => total + t.jumlah, 0);

  const pengeluaran = transaksi
    .filter((t) => t.jenis === 'pengeluaran')
    .reduce((total, t) => total + t.jumlah, 0);

  const saldo = pemasukan - pengeluaran;
  const rupiah = (n) => 'Rp' + n.toLocaleString('id-ID');

  return (
    <div className="ringkasan">
      <div className="saldo">
        <span>Saldo</span>
        <h2>{rupiah(saldo)}</h2>
      </div>
      <div className="detail">
        <p className="pemasukan">Masuk: {rupiah(pemasukan)}</p>
        <p className="pengeluaran">Keluar: {rupiah(pengeluaran)}</p>
      </div>
    </div>
  );
}

