export const initialState = [];

export function transaksiReducer(state, action) {
  switch (action.type) {
    case 'tambah':
      return [action.payload, ...state];
    case 'hapus':
      return state.filter((t) => t.id !== action.id);
    case 'edit':
      return state.map((t) =>
        t.id === action.payload.id ? { ...t, ...action.payload } : t,
      );
    case 'reset':
      return [];
    case 'set': // dipakai saat memuat dari localStorage
      return action.payload;
    default:
      return state;
  }
}

