import { createContext, useContext, useReducer, useEffect } from 'react';
import { transaksiReducer, initialState } from './transaksiReducer';

const KeuanganContext = createContext(null);

export function KeuanganProvider({ children }) {
  const [transaksi, dispatch] = useReducer(transaksiReducer, initialState);

  // muat dari localStorage sekali di awal
  useEffect(() => {
    const data = localStorage.getItem('transaksi');
    if (data) dispatch({ type: 'set', payload: JSON.parse(data) });
  }, []);

  // simpan setiap kali berubah
  useEffect(() => {
    localStorage.setItem('transaksi', JSON.stringify(transaksi));
  }, [transaksi]);

  return (
    <KeuanganContext.Provider value={{ transaksi, dispatch }}>
      {children}
    </KeuanganContext.Provider>
  );
}

export const useKeuangan = () => useContext(KeuanganContext);

