function Ringkasan() {
  const { transaksi } = useKeuangan();

  const { pemasukan, pengeluaran, saldo } = useMemo(() => {
    const masuk = transaksi
      .filter((t) => t.jenis === 'pemasukan')
      .reduce((s, t) => s + t.jumlah, 0);
    const keluar = transaksi
      .filter((t) => t.jenis === 'pengeluaran')
      .reduce((s, t) => s + t.jumlah, 0);
    return { pemasukan: masuk, pengeluaran: keluar, saldo: masuk - keluar };
  }, [transaksi]); // hanya hitung ulang saat transaksi berubah

  const rupiah = (n) => 'Rp' + n.toLocaleString('id-ID');
  return (
    <div className="ringkasan">
      <h2>{rupiah(saldo)}</h2>
      <p>Masuk: {rupiah(pemasukan)} · Keluar: {rupiah(pengeluaran)}</p>
    </div>
  );
}

