    setDeskripsi(''); setJumlah('');
    inputRef.current?.focus(); // fokus lagi setelah submit
  }

  return (
    <form onSubmit={handleSubmit}>
      <input ref={inputRef} placeholder="Deskripsi"
             value={deskripsi} onChange={(e) => setDeskripsi(e.target.value)} />
      {/* ... input jumlah & select jenis ... */}
      <button type="submit">Tambah</button>
    </form>
  );
}

