import { useState, useDeferredValue, useMemo, useTransition } from 'react';
import { useKeuangan } from '../state/KeuanganContext';

function PencarianTransaksi() {
  const { transaksi } = useKeuangan();
  const [keyword, setKeyword] = useState('');
  const [filter, setFilter] = useState('semua');
  const [isPending, startTransition] = useTransition();

  // tunda nilai berat untuk filtering
  const deferredKeyword = useDeferredValue(keyword);

  const hasil = useMemo(() => {
    return transaksi.filter((t) => {
      const cocokKata = t.deskripsi
        .toLowerCase()
        .includes(deferredKeyword.toLowerCase());
      const cocokJenis = filter === 'semua' || t.jenis === filter;
      return cocokKata && cocokJenis;
    });
  }, [transaksi, deferredKeyword, filter]);

  function gantiFilter(f) {
    startTransition(() => setFilter(f)); // tandai non-urgent
  }

  return (
    <>
      <input placeholder="Cari deskripsi..."
             value={keyword} onChange={(e) => setKeyword(e.target.value)} />
      <div className="filter">
        <button onClick={() => gantiFilter('semua')}>Semua</button>
        <button onClick={() => gantiFilter('pemasukan')}>Pemasukan</button>
        <button onClick={() => gantiFilter('pengeluaran')}>Pengeluaran</button>
      </div>
      {isPending && <span>Memperbarui...</span>}
      <DaftarTransaksi transaksi={hasil} />
    </>
  );
}

import { useLayoutEffect, useRef, useState } from 'react';

function BarRasio({ rasio }) { // rasio 0..1
  const wrapRef = useRef(null);
  const [lebar, setLebar] = useState(0);

  useLayoutEffect(() => {
    const total = wrapRef.current?.offsetWidth ?? 0;
    setLebar(total * rasio); // diterapkan sebelum paint -> mulus
  }, [rasio]);

  return (
    <div ref={wrapRef} className="bar-wrap">
      <div className="bar-isi" style={{ width: lebar }} />
    </div>
  );
}

import { useState, useEffect, useDebugValue } from 'react';

export function useLocalStorage(key, nilaiAwal) {
  const [nilai, setNilai] = useState(() => {
    const ada = localStorage.getItem(key);
    return ada ? JSON.parse(ada) : nilaiAwal;
  });

  useDebugValue(`${key}: ${Array.isArray(nilai) ? nilai.length + ' item' : nilai}`);

  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(nilai));
  }, [key, nilai]);

  return [nilai, setNilai];
}

import { useSyncExternalStore } from 'react';

export function useOnline() {
  return useSyncExternalStore(
    (cb) => {
      window.addEventListener('online', cb);
      window.addEventListener('offline', cb);
      return () => {
        window.removeEventListener('online', cb);
        window.removeEventListener('offline', cb);
      };
    },
    () => navigator.onLine, // snapshot client
    () => true,             // snapshot server
  );
}

