import { Platform } from 'react-native';

// Ganti dengan IP LAN komputermu saat memakai HP fisik
const IP_KOMPUTER = '192.168.1.10';

const HOST = Platform.select({
  android: `http://10.0.2.2:8080`,        // emulator Android
  ios:     `http://localhost:8080`,       // simulator iOS
  default: `http://${IP_KOMPUTER}:8080`,
});
const BASE = `${HOST}/api`;

// Satu pintu untuk semua request: timeout + JSON + error server
async function request(path, opsi = {}, timeoutMs = 8000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(`${BASE}${path}`, {
      headers: { 'Content-Type': 'application/json' },
      signal: controller.signal,
      ...opsi,
    });
    if (res.status === 204) return null;     // DELETE sukses (NoContent)
    const data = await res.json().catch(() => null);
    if (!res.ok) {
      // backend Go mengirim { "error": "pesan" } — lihat tulisError()
      throw new Error(data?.error ?? `HTTP ${res.status}`);
    }
    return data;
  } catch (e) {
    if (e.name === 'AbortError') {
      throw new Error('Server tidak merespons. Cek koneksi & alamat API.');
    }
    throw e;
  } finally {
    clearTimeout(timer);
  }
}

