export default function FormTransaksi({ onSukses }) {
  const [jenis, setJenis] = useState('pengeluaran');
  const [deskripsi, setDeskripsi] = useState('');
  const [jumlah, setJumlah] = useState('');
  const [mengirim, setMengirim] = useState(false);
  const [galat, setGalat] = useState(null);

  // cermin dari validasi() di internal/service/keuangan.go
  const validasiLokal = () => {
    if (!deskripsi.trim()) return 'deskripsi wajib diisi';
    if (!(Number(jumlah) > 0)) return 'jumlah harus lebih dari 0';
    return null;
  };

  const kirim = async () => {
    const salah = validasiLokal();
    if (salah) return setGalat(salah);

    setMengirim(true);
    setGalat(null);
    try {
      const baru = await tambahTransaksi({
        jenis,
        deskripsi: deskripsi.trim(),
        jumlah: Number(jumlah),       // TextInput selalu string!
      });
      onSukses(baru);                 // kirim balik transaksi ber-ID
      setDeskripsi(''); setJumlah('');
    } catch (e) {
      setGalat(e.message);            // termasuk pesan ErrValidasi dari Go
    } finally {
      setMengirim(false);
    }
  };

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}>
      <View style={styles.pilihan}>
        {['pemasukan', 'pengeluaran'].map((j) => (
          <Pressable key={j} onPress={() => setJenis(j)}
            style={[styles.opsi, jenis === j && styles.opsiAktif]}>
            <Text style={jenis === j ? styles.teksAktif : null}>{j}</Text>
          </Pressable>
        ))}
      </View>

      <TextInput style={styles.input} placeholder="Deskripsi"
        value={deskripsi} onChangeText={setDeskripsi} />
      <TextInput style={styles.input} placeholder="Jumlah (Rp)"
        value={jumlah} onChangeText={setJumlah}
        keyboardType="numeric" />

      {galat && <Text style={styles.galat}>{galat}</Text>}

      <Pressable style={styles.tombol} onPress={kirim} disabled={mengirim}>
        {mengirim
          ? <ActivityIndicator color="white" />
          : <Text style={styles.teksTombol}>Simpan</Text>}
      </Pressable>
    </KeyboardAvoidingView>
  );
}

