import AsyncStorage from '@react-native-async-storage/async-storage';
import { useCallback, useEffect, useRef, useState } from 'react';
import { ambilTransaksi } from '../api';

const KUNCI = 'cache:transaksi';

export function useTransaksi() {
  const [data, setData] = useState([]);
  const [memuat, setMemuat] = useState(true);
  const [galat, setGalat] = useState(null);
  const hidup = useRef(true);

  const muat = useCallback(async () => {
    setGalat(null);
    try {
      const hasil = await ambilTransaksi();
      if (!hidup.current) return;
      setData(hasil ?? []);
      await AsyncStorage.setItem(KUNCI, JSON.stringify(hasil ?? []));
    } catch (e) {
      if (hidup.current) setGalat('Offline — menampilkan data tersimpan');
    } finally {
      if (hidup.current) setMemuat(false);
    }
  }, []);

  useEffect(() => {
    hidup.current = true;
    (async () => {
      const cache = await AsyncStorage.getItem(KUNCI);  // 1) cache dulu
      if (cache && hidup.current) setData(JSON.parse(cache));
      muat();                                           // 2) lalu server
    })();
    return () => { hidup.current = false; };
  }, [muat]);

  return { data, setData, memuat, galat, muat };
}

