import { useCallback, useEffect, useState } from 'react';   // (ilustratif)
import type { Transaksi } from '../types';
import { ambilTransaksi } from '../api';

// tipe kembalian hook dideklarasikan eksplisit = kontrak bagi pemakainya
interface HasilUseTransaksi {
  data: Transaksi[];
  memuat: boolean;
  galat: string | null;
  muat: () => Promise<void>;
}

export function useTransaksi(): HasilUseTransaksi {
  const [data, setData] = useState<Transaksi[]>([]);   // bukan any[]!
  const [memuat, setMemuat] = useState<boolean>(true);
  const [galat, setGalat] = useState<string | null>(null);

  const muat = useCallback(async () => {
    setMemuat(true); setGalat(null);
    try { setData(await ambilTransaksi()); }
    catch (e) { setGalat(e instanceof Error ? e.message : 'Gagal'); }
    finally { setMemuat(false); }
  }, []);

  useEffect(() => { muat(); }, [muat]);
  return { data, memuat, galat, muat };
}

