import { Component, input, output, model, computed } from '@angular/core';

@Component({
  selector: 'app-item-keranjang',
  template: `
    <p>{{ produk().nama }} — {{ subtotal() }}</p>
    <input type="number" [(ngModel)]="jumlah" />
    <button (click)="hapus.emit(produk().id)">Hapus</button>
  `,
})
export class ItemKeranjang {
  // input wajib: compiler memaksa pemanggil mengisinya
  produk = input.required<Produk>();

  // input opsional dengan nilai bawaan
  diskon = input(0);

  // transform: mengubah nilai masuk (mis. string "5" jadi number 5)
  stok = input(0, { transform: (v: string | number) => Number(v) });

  // model: input + output sekaligus (two-way binding)
  jumlah = model(1);

  // output: memancarkan event ke induk
  hapus = output<number>();

  // input adalah signal, jadi bisa langsung dipakai di computed
  subtotal = computed(() =>
    this.produk().harga * this.jumlah() * (1 - this.diskon() / 100)
  );
}

export class HalamanProduk implements OnInit, OnDestroy {
