    this.service.streamProduk()
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(data => this.produk.set(data));
  }

  ngOnDestroy() {
    // hanya untuk resource non-RxJS: timer, event listener manual, chart library
  }
}

