export function tidakBolehMengandung(kata: string): ValidatorFn {
  return (control: AbstractControl): ValidationErrors | null => {
    const nilai = String(control.value ?? '').toLowerCase();
    return nilai.includes(kata) ? { mengandungKata: { kata } } : null;
