@Injectable({ providedIn: 'root' })
export class ProdukApi {
  private http = inject(HttpClient);
  private base = '/api/produk';

  daftar(kategori?: string): Observable<Produk[]> {
    let params = new HttpParams();
    if (kategori) params = params.set('kategori', kategori);
    return this.http.get<Produk[]>(this.base, { params });
  }

  detail(id: number) { return this.http.get<Produk>(`${this.base}/${id}`); }
  buat(data: Omit<Produk, 'id'>) { return this.http.post<Produk>(this.base, data); }
  ubah(id: number, data: Partial<Produk>) { return this.http.patch<Produk>(`${this.base}/${id}`, data); }
  hapus(id: number) { return this.http.delete<void>(`${this.base}/${id}`); }
}

import { HttpInterceptorFn } from '@angular/common/http';

// menyisipkan token pada setiap permintaan
export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const token = inject(AuthService).token();
  if (!token) return next(req);

  return next(req.clone({
    setHeaders: { Authorization: `Bearer ${token}` },
  }));
};

// menangani error secara terpusat
export const errorInterceptor: HttpInterceptorFn = (req, next) => {
  const notif = inject(NotifikasiService);
  const auth = inject(AuthService);

  return next(req).pipe(
    retry({ count: 2, delay: 1000 }),        // ulangi 2x untuk gangguan sesaat
    catchError((err: HttpErrorResponse) => {
      if (err.status === 401) auth.keluar();
      else if (err.status === 0) notif.error('Tidak ada koneksi internet.');
      else if (err.status >= 500) notif.error('Server sedang bermasalah.');
      return throwError(() => err);
    }),
  );
};

