import { Injectable, computed, signal, inject } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class KeranjangService {
  private api = inject(PesananApi);

  // ---- STATE PRIVAT: hanya service ini yang boleh menulis ----
  private _items = signal<ItemKeranjang[]>([]);
  private _sedangKirim = signal(false);
  private _error = signal<string | null>(null);

  // ---- PEMBACAAN PUBLIK: komponen hanya bisa membaca ----
  readonly items = this._items.asReadonly();
  readonly sedangKirim = this._sedangKirim.asReadonly();
  readonly error = this._error.asReadonly();

  // ---- TURUNAN: dihitung, tidak pernah disimpan ----
  readonly jumlahItem = computed(() => this._items().reduce((n, i) => n + i.qty, 0));
  readonly total = computed(() => this._items().reduce((t, i) => t + i.harga * i.qty, 0));
  readonly kosong = computed(() => this._items().length === 0);

  // ---- AKSI: satu-satunya cara mengubah state ----
  tambah(produk: Produk) {
    this._items.update(list => {
      const ada = list.find(i => i.id === produk.id);
      return ada
        ? list.map(i => i.id === produk.id ? { ...i, qty: i.qty + 1 } : i)
        : [...list, { ...produk, qty: 1 }];
    });
  }

  ubahQty(id: number, qty: number) {
    if (qty <= 0) return this.hapus(id);
    this._items.update(list => list.map(i => i.id === id ? { ...i, qty } : i));
  }

  hapus(id: number) {
    this._items.update(list => list.filter(i => i.id !== id));
  }

  kosongkan() { this._items.set([]); }

  async checkout() {
    this._sedangKirim.set(true);
    this._error.set(null);
    try {
      await firstValueFrom(this.api.buatPesanan(this._items()));
      this._items.set([]);
    } catch {
      this._error.set('Gagal membuat pesanan. Coba lagi.');
    } finally {
      this._sedangKirim.set(false);
    }
  }
}

