import { signalStore, withState, withComputed, withMethods, patchState }
  from '@ngrx/signals';
import { computed, inject } from '@angular/core';

interface KeranjangState {
  items: ItemKeranjang[];
  sedangKirim: boolean;
  error: string | null;
}

const awal: KeranjangState = { items: [], sedangKirim: false, error: null };

export const KeranjangStore = signalStore(
  { providedIn: 'root' },              // atau dihilangkan agar disediakan per rute

  withState(awal),

  // nilai turunan — setiap field otomatis menjadi signal
  withComputed(({ items }) => ({
    jumlahItem: computed(() => items().reduce((n, i) => n + i.qty, 0)),
    total:      computed(() => items().reduce((t, i) => t + i.harga * i.qty, 0)),
    kosong:     computed(() => items().length === 0),
  })),

  // aksi
  withMethods((store, api = inject(PesananApi)) => ({
    tambah(produk: Produk) {
      const ada = store.items().find(i => i.id === produk.id);
      patchState(store, {
        items: ada
          ? store.items().map(i => i.id === produk.id ? { ...i, qty: i.qty + 1 } : i)
          : [...store.items(), { ...produk, qty: 1 }],
      });
    },

    hapus(id: number) {
      patchState(store, { items: store.items().filter(i => i.id !== id) });
    },

    async checkout() {
      patchState(store, { sedangKirim: true, error: null });
      try {
        await firstValueFrom(api.buatPesanan(store.items()));
        patchState(store, { items: [] });
      } catch {
        patchState(store, { error: 'Gagal membuat pesanan.' });
      } finally {
        patchState(store, { sedangKirim: false });
      }
    },
  })),

  // lifecycle
  withHooks({
    onInit(store) { console.log('store siap', store.items()); },
    onDestroy()   { console.log('store dibuang'); },
  }),
);

// pemakaian di komponen: setiap field state & computed adalah signal
@Component({
  template: `
    <p>{{ store.jumlahItem() }} item — {{ store.total() }}</p>
    <button (click)="store.checkout()" [disabled]="store.sedangKirim()">Checkout</button>
  `,
