import { withEntities, setAllEntities, addEntity, removeEntity, updateEntity }
  from '@ngrx/signals/entities';

export const ProdukStore = signalStore(
  { providedIn: 'root' },
  withEntities<Produk>(),                 // menyediakan entities(), entityMap(), ids()
  withState({ sedangMuat: false, filter: '' }),

  withComputed(({ entities, filter }) => ({
    terfilter: computed(() =>
      entities().filter(p => p.nama.toLowerCase().includes(filter().toLowerCase()))
    ),
    jumlah: computed(() => entities().length),
  })),

  withMethods((store, api = inject(ProdukApi)) => ({
    async muat() {
      patchState(store, { sedangMuat: true });
      const data = await firstValueFrom(api.daftar());
      patchState(store, setAllEntities(data), { sedangMuat: false });
    },
    tambah(p: Produk)                 { patchState(store, addEntity(p)); },
    hapus(id: number)                 { patchState(store, removeEntity(id)); },
    ubah(id: number, ubahan: Partial<Produk>) {
      patchState(store, updateEntity({ id, changes: ubahan }));
    },
  })),
);

import { rxMethod } from '@ngrx/signals/rxjs-interop';

withMethods((store, api = inject(ProdukApi)) => ({
  // menerima signal atau nilai; pipeline RxJS penuh tersedia
  cari: rxMethod<string>(
    pipe(
      debounceTime(300),
      distinctUntilChanged(),
      tap(() => patchState(store, { sedangMuat: true })),
      switchMap(kata => api.cari(kata).pipe(
        tapResponse({
          next: (data) => patchState(store, setAllEntities(data), { sedangMuat: false }),
          error: () => patchState(store, { sedangMuat: false, error: 'Gagal mencari' }),
        }),
      )),
    ),
  ),
}))

