export function withStatusMuat() {
  return signalStoreFeature(
    withState({ sedangMuat: false, error: null as string | null }),
    withMethods((store) => ({
      mulaiMuat() { patchState(store, { sedangMuat: true, error: null }); },
      selesaiMuat() { patchState(store, { sedangMuat: false }); },
      gagalMuat(pesan: string) { patchState(store, { sedangMuat: false, error: pesan }); },
    })),
  );
}

