async sukai(id: number) {
  const sebelumnya = this.store.items();          // simpan untuk rollback

  // 1. perbarui UI segera
  patchState(this.store, {
    items: sebelumnya.map(i => i.id === id ? { ...i, disukai: true } : i),
  });

  try {
    // 2. kirim ke server
    await firstValueFrom(this.api.sukai(id));
  } catch {
    // 3. gagal: kembalikan ke keadaan semula dan beri tahu pengguna
    patchState(this.store, { items: sebelumnya });
    this.notif.error('Gagal menyimpan. Coba lagi.');
  }
}

export const EditorStore = signalStore(
  withState({ konten: '', riwayat: [] as string[], posisi: -1 }),

  withComputed(({ riwayat, posisi }) => ({
    bisaUndo: computed(() => posisi() > 0),
    bisaRedo: computed(() => posisi() < riwayat().length - 1),
  })),

  withMethods((store) => ({
    tulis(konten: string) {
      // buang riwayat "masa depan" saat pengguna mengetik setelah undo
      const riwayatBaru = [...store.riwayat().slice(0, store.posisi() + 1), konten];
      patchState(store, {
        konten,
        riwayat: riwayatBaru,
        posisi: riwayatBaru.length - 1,
      });
    },
    undo() {
      if (store.posisi() <= 0) return;
      const posisiBaru = store.posisi() - 1;
      patchState(store, { posisi: posisiBaru, konten: store.riwayat()[posisiBaru] });
    },
    redo() {
      if (store.posisi() >= store.riwayat().length - 1) return;
      const posisiBaru = store.posisi() + 1;
      patchState(store, { posisi: posisiBaru, konten: store.riwayat()[posisiBaru] });
    },
  })),
);

