export class SinkronTabService {
  private channel = new BroadcastChannel('app-state');
  private auth = inject(AuthService);

  constructor() {
    // terima perubahan dari tab lain
    this.channel.onmessage = (e) => {
      if (e.data.tipe === 'logout') this.auth.bersihkanSesiLokal();
      if (e.data.tipe === 'keranjang') this.keranjang.setDariTabLain(e.data.items);
    };
  }

  siarkan(tipe: string, data?: unknown) {
    this.channel.postMessage({ tipe, ...(data ? { data } : {}) });
  }
}

