let transaksi = [
  { id: 1, jenis: 'pemasukan',   deskripsi: 'Gaji',       jumlah: 5000000, tanggal: new Date().toISOString() },
  { id: 2, jenis: 'pengeluaran', deskripsi: 'Makan siang', jumlah: 35000,   tanggal: new Date().toISOString() },
];
let urutanId = 3;   // penghasil id sederhana

export const store = {
  semua: () => transaksi,
  cari: (id) => transaksi.find((t) => t.id === id),
  tambah: (data) => {
    const baru = { id: urutanId++, ...data, tanggal: new Date().toISOString() };
    transaksi.push(baru);
    return baru;
  },
  ubah: (id, data) => {
    const t = transaksi.find((x) => x.id === id);
    if (!t) return null;
    Object.assign(t, data);
    return t;
  },
  hapus: (id) => {
    const sebelum = transaksi.length;
    transaksi = transaksi.filter((x) => x.id !== id);
    return transaksi.length < sebelum;   // true jika ada yang terhapus
  },
};

