import { Router } from 'express';
import { store } from '../data/store.js';

const router = Router();

// GET /api/transaksi — daftar
router.get('/', (req, res) => {
  res.json(store.semua());
});

// POST /api/transaksi — tambah
router.post('/', (req, res) => {
  const { jenis, deskripsi, jumlah } = req.body;

  // validasi sederhana (akan diperkuat di Dokumen 2)
  if (!deskripsi || !deskripsi.trim()) {
    return res.status(400).json({ error: 'deskripsi wajib diisi' });
  }
  if (!(Number(jumlah) > 0)) {
    return res.status(400).json({ error: 'jumlah harus lebih dari 0' });
  }
  if (!['pemasukan', 'pengeluaran'].includes(jenis)) {
    return res.status(400).json({ error: 'jenis tidak valid' });
  }

  const baru = store.tambah({ jenis, deskripsi: deskripsi.trim(), jumlah: Number(jumlah) });
  res.status(201).json(baru);   // 201 + transaksi ber-id
});

// PUT /api/transaksi/:id — ubah
router.put('/:id', (req, res) => {
  const id = Number(req.params.id);
  const hasil = store.ubah(id, req.body);
  if (!hasil) {
    return res.status(404).json({ error: 'transaksi tidak ditemukan' });
  }
  res.json(hasil);
});

// DELETE /api/transaksi/:id — hapus
router.delete('/:id', (req, res) => {
  const id = Number(req.params.id);
  const terhapus = store.hapus(id);
  if (!terhapus) {
    return res.status(404).json({ error: 'transaksi tidak ditemukan' });
  }
  res.status(204).end();   // 204 No Content (tanpa body)
});

export default router;

