// GET /api/ringkasan — hitung pemasukan, pengeluaran, saldo
router.get('/', (req, res) => {
  const data = store.semua();
  const pemasukan = data
    .filter((t) => t.jenis === 'pemasukan')
    .reduce((total, t) => total + t.jumlah, 0);
  const pengeluaran = data
    .filter((t) => t.jenis === 'pengeluaran')
    .reduce((total, t) => total + t.jumlah, 0);

  res.json({ pemasukan, pengeluaran, saldo: pemasukan - pengeluaran });
});

