  jumlah: z.number().positive('jumlah harus lebih dari 0'),
});

export async function buatTransaksi(input) {
  const hasil = skemaTransaksi.safeParse(input);
  if (!hasil.success) {
    // lempar error tervalidasi → ditangkap error middleware (Bab 3)
    const pesan = hasil.error.issues[0].message;
    throw new AppError(pesan, 400);
  }
  return repo.simpan(hasil.data);
}

export async function semuaTransaksi() {
  return repo.semua();
}

export async function hapusTransaksi(id) {
  const ada = await repo.hapus(id);
  if (!ada) throw new AppError('transaksi tidak ditemukan', 404);
}

export async function ringkasan() {
  const data = await repo.semua();
  const pemasukan = data.filter((t) => t.jenis === 'pemasukan').reduce((s, t) => s + t.jumlah, 0);
  const pengeluaran = data.filter((t) => t.jenis === 'pengeluaran').reduce((s, t) => s + t.jumlah, 0);
  return { pemasukan, pengeluaran, saldo: pemasukan - pengeluaran };
}

