// Kelas error aplikasi: membawa status HTTP
export class AppError extends Error {
  constructor(pesan, status = 500) {
    super(pesan);
    this.status = status;
  }
}

// Pembungkus async: tangkap error dari handler async → teruskan ke error middleware
export const bungkus = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// Middleware error TERPUSAT (4 argumen: err, req, res, next)
export function tanganiError(err, req, res, next) {
  const status = err.status ?? 500;
  if (status === 500) console.error(err);   // log bug server, bukan error validasi
  res.status(status).json({ error: err.message ?? 'terjadi kesalahan' });
}

