import { Injectable, NotFoundException } from '@nestjs/common';
import { BuatTransaksiDto } from './dto/buat-transaksi.dto';

export interface Transaksi {
  id: number;
  jenis: string;
  deskripsi: string;
  jumlah: number;
  tanggal: string;
}

@Injectable()
export class TransaksiService {
  private data: Transaksi[] = [];   // in-memory dulu (DB di Dokumen 2)
  private urutanId = 1;

  semua(): Transaksi[] {
    return this.data;
  }

  buat(dto: BuatTransaksiDto): Transaksi {
    const baru: Transaksi = {
      id: this.urutanId++,
      ...dto,
      deskripsi: dto.deskripsi.trim(),
      tanggal: new Date().toISOString(),
    };
    this.data.push(baru);
    return baru;
  }

  hapus(id: number): void {
    const idx = this.data.findIndex((t) => t.id === id);
    if (idx === -1) throw new NotFoundException('transaksi tidak ditemukan');
    this.data.splice(idx, 1);
  }

  ringkasan() {
    const pemasukan = this.data.filter((t) => t.jenis === 'pemasukan').reduce((s, t) => s + t.jumlah, 0);
    const pengeluaran = this.data.filter((t) => t.jenis === 'pengeluaran').reduce((s, t) => s + t.jumlah, 0);
    return { pemasukan, pengeluaran, saldo: pemasukan - pengeluaran };
  }
}

