// src/common/http-exception.filter.ts
import { ArgumentsHost, Catch, ExceptionFilter, HttpException, HttpStatus } from '@nestjs/common';

@Catch()                                          // tangkap SEMUA exception
export class FilterErrorGlobal implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const res = ctx.getResponse();

    const status = exception instanceof HttpException
      ? exception.getStatus()
      : HttpStatus.INTERNAL_SERVER_ERROR;

    // ambil pesan; untuk error validasi, Nest menaruh array pesan
    let pesan = 'terjadi kesalahan';
    if (exception instanceof HttpException) {
      const r = exception.getResponse() as any;
      pesan = Array.isArray(r?.message) ? r.message[0] : (r?.message ?? r);
    }

    res.status(status).json({ error: pesan });    // bentuk seragam { error }
  }
}

