import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { TransaksiEntity } from './transaksi.entity';

@Injectable()
export class TransaksiService {
  constructor(
    @InjectRepository(TransaksiEntity)
    private readonly repo: Repository<TransaksiEntity>,   // disuntik oleh Nest
  ) {}

  semua() {
    return this.repo.find({ order: { id: 'DESC' } });
  }

  buat(dto: BuatTransaksiDto) {
    const t = this.repo.create(dto);     // buat instance entity
    return this.repo.save(t);            // INSERT, balas dengan id
  }

  async hapus(id: number) {
    const hasil = await this.repo.delete(id);
    if (hasil.affected === 0) throw new NotFoundException('transaksi tidak ditemukan');
  }

  async ringkasan() {
    const data = await this.repo.find();
    const pemasukan = data.filter((t) => t.jenis === 'pemasukan').reduce((s, t) => s + Number(t.jumlah), 0);
    const pengeluaran = data.filter((t) => t.jenis === 'pengeluaran').reduce((s, t) => s + Number(t.jumlah), 0);
    return { pemasukan, pengeluaran, saldo: pemasukan - pengeluaran };
  }
}

