// middleware.ts — berjalan di EDGE untuk setiap request yang cocok
import { NextRequest, NextResponse } from 'next/server';

export const config = { matcher: '/' };

export function middleware(req: NextRequest) {
  // Use case: A/B test hero landing Pencatat Keuangan
  const bucket = req.cookies.get('ab-hero')?.value
    ?? (Math.random() < 0.5 ? 'a' : 'b');

  const res = bucket === 'b'
    ? NextResponse.rewrite(new URL('/hero-b', req.url))   // varian B
    : NextResponse.next();

  res.cookies.set('ab-hero', bucket, { maxAge: 60 * 60 * 24 * 30 });
  res.headers.set('x-geo', req.geo?.country ?? 'ID');     // personalisasi geo
  return res;
