// middleware.ts — nonce unik per request (edge, dari Fase 1)
import { NextResponse } from 'next/server';

export function middleware() {
  const nonce = crypto.randomUUID().replace(/-/g, '');
  const csp = [
    `default-src 'self'`,
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'`,  // hanya script ber-nonce + turunannya
    `object-src 'none'`, `base-uri 'none'`,
    `require-trusted-types-for 'script'`,                   // aktifkan Trusted Types
  ].join('; ');

  const res = NextResponse.next();
  res.headers.set('Content-Security-Policy', csp);          // enforce
  res.headers.set('x-nonce', nonce);                        // dipakai render <script nonce>
  return res;
}

