// useFetch — pengambilan data reusable dengan loading/error/cleanup
function useFetch(url) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  useEffect(() => {
    let aktif = true;
    setLoading(true);
    fetch(url).then(r => r.json())
      .then(d => { if (aktif) setData(d); })
      .catch(e => { if (aktif) setError(e); })
      .finally(() => { if (aktif) setLoading(false); });
    return () => { aktif = false; };
  }, [url]);
  return { data, loading, error };
}

// useDebounce — tunda nilai sampai user berhenti mengetik
function useDebounce(nilai, delay = 500) {
  const [debounced, setDebounced] = useState(nilai);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(nilai), delay);
    return () => clearTimeout(t);  // batalkan timer lama tiap kali nilai berubah
  }, [nilai, delay]);
  return debounced;
}

