import { useState, useCallback } from 'react';

export function useToggle(awal = false) {
  const [nilai, set] = useState(awal);
  const toggle = useCallback(() => set(v => !v), []);
  return [nilai, toggle];
}

import { useState, useEffect } from 'react';

export function useDebounce(nilai, delay = 400) {
  const [debounced, setDebounced] = useState(nilai);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(nilai), delay);
    return () => clearTimeout(t);
  }, [nilai, delay]);
  return debounced;
}

import { useState, useEffect } from 'react';

export function useFetch(url) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  useEffect(() => {
    let aktif = true;
    setLoading(true);
    fetch(url).then(r => r.json())
      .then(d => { if (aktif) setData(d); })
      .catch(e => { if (aktif) setError(e); })
      .finally(() => { if (aktif) setLoading(false); });
    return () => { aktif = false; };
  }, [url]);
  return { data, loading, error };
}

