import { createContext, useContext, useReducer } from 'react';

const KeranjangContext = createContext(null);

function reducer(state, action) {
  switch (action.type) {
    case 'tambah':   return [...state, action.produk];
    case 'hapus':    return state.filter(p => p.id !== action.id);
    default:         return state;
  }
}

export function KeranjangProvider({ children }) {
  const [items, dispatch] = useReducer(reducer, []);
  return (
    <KeranjangContext.Provider value={{ items, dispatch }}>
      {children}
    </KeranjangContext.Provider>
  );
}

export const useKeranjang = () => useContext(KeranjangContext);

import { create } from 'zustand';

export const useKeranjang = create((set) => ({
  items: [],
  tambah: (p) => set((s) => ({ items: [...s.items, p] })),
  hapus:  (id) => set((s) => ({ items: s.items.filter(i => i.id !== id) })),
  kosongkan: () => set({ items: [] }),
}));

// pakai di komponen mana pun, tanpa Provider:
function IkonKeranjang() {
  const jumlah = useKeranjang((s) => s.items.length); // selektor
  return <span>{jumlah}</span>;
}

import { createSlice, configureStore } from '@reduxjs/toolkit';

const keranjangSlice = createSlice({
  name: 'keranjang',
  initialState: { items: [] },
  reducers: {
    tambah: (state, action) => { state.items.push(action.payload); }, // Immer: aman 'mutasi'
    hapus:  (state, action) => {
      state.items = state.items.filter(i => i.id !== action.payload);
    },
  },
});

export const { tambah, hapus } = keranjangSlice.actions;
export const store = configureStore({
  reducer: { keranjang: keranjangSlice.reducer },
});

