// mutasi + refresh cache otomatis
function useTambahProduk() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (baru) => fetch('/api/produk', { method: 'POST', body: JSON.stringify(baru) }),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['produk'] }),
  });
}

// interface: mendeskripsikan bentuk objek — paling sering dipakai untuk model data
export interface Produk {
  id: number;
  nama: string;
  harga: number;
  deskripsi?: string;        // tanda ? = opsional, boleh tidak ada
  readonly dibuatPada: Date; // tidak boleh diubah setelah dibuat
}

// type alias: lebih fleksibel, bisa union & intersection
export type StatusPesanan = 'menunggu' | 'diproses' | 'dikirim' | 'selesai';
export type ProdukDenganStok = Produk & { stok: number };

// union type membuat kondisi menjadi eksplisit dan diperiksa compiler
function warnaStatus(status: StatusPesanan): string {
  switch (status) {
    case 'menunggu':  return 'abu';
    case 'diproses':  return 'biru';
    case 'dikirim':   return 'ungu';
    case 'selesai':   return 'hijau';
    // tanpa default: compiler memperingatkan bila ada status baru yang belum ditangani
  }
}

